import { useEffect } from "react";
import { Link } from "react-router-dom"

const Admin = () => {

    const getdata = () => {

        let url = "http://localhost:1111/main/list";

        try{
            fetch(url)
            .then( res => res.json() )
            .then( info => {
                console.log(info)
            })
        }catch(error){
            console.log(" Loading error... ");

        }
    }

    useEffect( () => {
        getdata()
    }, [])

    return(
        <div className="container">
            <div className="row justify-content-center mt-5">
            <Link to="/adminbook" > <button className="btn btn-primary" > Booking List </button> </Link>
                <div className="col-8 " >
                    <table className="table table-striped" >
                        <thead>
                            <tr>
                                <th>Id</th>
                                <th>Room Name</th>
                                <th>Image Address</th>
                            </tr>
                        </thead>
                        <tbody>
                            <tr>
                                <td>1</td>
                                <td>Prayer Room</td>
                                <td>Jesus</td>
                            </tr>
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    )
}

export default Admin
